1	export function isNewLocation(url: string) {
2	  url = url.replace(/^\/[a-z]{2}\//, '/');
3	  if (url === '/x' || url === '/x/') {
4	    // skipped if it is the X marketing page
5	    return false;
6	  }
7	  return (
8	    url.startsWith('/x') ||
9	    url.startsWith('/material-ui') ||
10	    url.startsWith('/base') ||
11	    url.startsWith('/joy-ui') ||
12	    url.startsWith('/system')
13	  );
14	}
15	
16	export const replaceMaterialLinks = (url: string) => {
17	  if (isNewLocation(url)) {
18	    return url;
19	  }
20	  return url.replace(
21	    /(guides|customization|getting-started|discover-more|experimental-api|migration)/,
22	    'material-ui/$1',
23	  );
24	};
25	
26	export const replaceComponentLinks = (url: string) => {
27	  if (isNewLocation(url)) {
28	    return url;
29	  }
30	  url = url.replace(/\/components\/data-grid/, '/x/react-data-grid');
31	  if (isNewLocation(url)) {
32	    return url;
33	  }
34	  if (url.startsWith('/customization')) {
35	    url = url.replace('customization', 'material-ui/customization');
36	  } else if (url.match(/components\/(icons|material-icons|transitions|pickers|about-the-lab)/)) {
37	    url = url.replace(/\/components\/(.*)/, '/material-ui/$1');
38	  } else {
39	    url = url.replace(/\/components\/(.*)/, '/material-ui/react-$1');
40	
41	    // TODO remove, fix the markdown files to match the URLs
42	    if (!url.match(/\/react-(tabs|breadcrumbs)/)) {
43	      url = url
44	        .replace(/(react-[-a-z]+)(x|ch)es([^a-z-])/, '$1$2$3')
45	        .replace(/(react-[-a-z]+)s([^a-z-])/, '$1$2')
46	        .replace(/(react-[-a-z]+)(x|ch)es$/, '$1$2')
47	        .replace(/(react-[-a-z]+)s$/, '$1')
48	        .replace(/react-trap-focu/, 'react-trap-focus')
49	        .replace(/react-circular-progres/, 'react-circular-progress')
50	        .replace(/react-linear-progres/, 'react-linear-progress')
51	        .replace(/react-progres/, 'react-progress');
52	    }
53	  }
54	  return url;
55	};
56	
57	export const replaceAPILinks = (url: string) => {
58	  if (isNewLocation(url) || !url.replace(/^\/[a-zA-Z]{2}\//, '/').startsWith('/api')) {
59	    return url;
60	  }
61	  url = url
62	    .replace(/\/api\/data-grid(.*)/, '/x/api/data-grid$1')
63	    .replace(
64	      /\/api\/(unstable-trap-focus|click-away-listener|no-ssr|portal|textarea-autosize)(.*)/,
65	      '/base-ui/api/$1$2',
66	    )
67	    .replace(/\/api\/([^/]+-unstyled)(.*)/, '/base-ui/api/$1$2');
68	
69	  if (isNewLocation(url)) {
70	    return url;
71	  }
72	
73	  url = url.replace(
74	    /\/api\/(loading-button|tab-list|tab-panel|date-picker|date-time-picker|time-picker|calendar-picker|calendar-picker-skeleton|desktop-picker|mobile-date-picker|month-picker|pickers-day|static-date-picker|year-picker|masonry|timeline|timeline-connector|timeline-content|timeline-dot|timeline-item|timeline-opposite-content|timeline-separator|unstable-trap-focus|tree-item|tree-view)(.*)/,
75	    '/material-ui/api/$1$2',
76	  );
77	
78	  if (isNewLocation(url)) {
79	    return url;
80	  }
81	
82	  return url.replace(/\/api\/(.*)/, '/material-ui/api/$1');
83	};
84	
85	export default function replaceUrl(url: string, asPath: string) {
86	  if (isNewLocation(asPath)) {
87	    url = replaceMaterialLinks(replaceAPILinks(replaceComponentLinks(url)));
88	    url = url.replace(/^\/styles\/(.*)/, '/system/styles/$1');
89	    url = url.replace(/^\/([a-z]{2})\/styles\/(.*)/, '/$1/system/styles/$2');
90	  }
91	  return url;
92	}
